/// getter, the compiler keeps the initial value only to infer the property's type
/// and never runs it.
@_documentation(visibility: private)
@attached(accessor, names: named(get))
public macro _StoragePublisherProjection() = #externalMacro(
    module: "FoundationToolboxMacros",
    type: "StoragePublisherProjectionMacro"
)
